package wgmodern;
import java.util.*;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import net.minecraft.tags.ItemTags;import net.minecraftforge.registries.RegistryObject;
public class Metallurgy {
 public static final Map<String,RegistryObject<Item>> CLUSTERS=new LinkedHashMap<>();
 public static final List<String> METALS=List.of("aluminum","cobalt","ardite","nickel","fz_dark_iron","manganese","zinc","platinum","ignatius","shadow_iron","lemurite","midasium","vyroxeres","ceruclase","alduorite","kalendrite","vulcanite","sanguinite","prometheum","deep_iron","infuscolium","oureclase","astral_silver","carmot","mithril","rubracium","orichalcum","adamantine","atlarus","eximite","meutoite");
 public static void register(){for(String metal:METALS){CLUSTERS.put(metal,Content.ITEMS.register(metal+"_cluster",()->new Cluster(metal)));var ore=ItemTags.create(new ResourceLocation("forge","ores/"+metal));tc4revival.content.SpecialMining.register(new ResourceLocation("witchinggadgets",metal),stack->enabled(metal)&&(stack.is(ore)||stack.is(ItemTags.create(new ResourceLocation("forge","raw_materials/"+metal)))),()->new ItemStack(CLUSTERS.get(metal).get()),1f);}}
 public static boolean enabled(String metal){return WGConfig.CLUSTERS.get()&&(!BlastRecipe.tagged("forge:ores/"+metal,1).isEmpty()||!BlastRecipe.tagged("forge:raw_materials/"+metal,1).isEmpty())&&!BlastRecipe.tagged("forge:ingots/"+metal,1).isEmpty();}
 public static class Cluster extends Item {public final String metal;public Cluster(String metal){super(new Properties());this.metal=metal;}@Override public String getDescriptionId(){return "item.WG_Cluster";}@Override public Component getName(ItemStack stack){var ingot=BlastRecipe.tagged("forge:ingots/"+metal,1);String name=ingot.isEmpty()?metal:ingot.getHoverName().getString();int end=name.lastIndexOf(' ');if(end>0)name=name.substring(0,end);return Component.translatable(getDescriptionId(),name);}}
 public static void init(){thaumcraft.api.research.ResearchCategories.registerEnablement("witchinggadgets:METALLURGICPERFECTION_CLUSTERS",()->WGConfig.CLUSTERS.get());thaumcraft.api.research.ResearchCategories.registerEnablement("witchinggadgets:METALLURGICPERFECTION_TRANSMUTATION",()->WGConfig.TRANSMUTATIONS.get());thaumcraft.api.research.ResearchPrerequisites.register(new ResourceLocation("witchinggadgets","metal_parents"),(entry,catalog,parents)->{String prefix=entry.key().equals("witchinggadgets:METALLURGICPERFECTION_CLUSTERS")?"PURE":entry.key().equals("witchinggadgets:METALLURGICPERFECTION_TRANSMUTATION")?"TRANS":null;if(prefix==null)return parents;var visible=new ArrayList<>(parents.visible());for(String metal:List.of("COPPER","TIN","SILVER","LEAD"))if(catalog.find(prefix+metal).isPresent()&&!visible.contains(prefix+metal))visible.add(prefix+metal);return new thaumcraft.api.research.ResearchPrerequisites.Parents(visible,parents.hidden());});}
}
